using Microsoft.Data.SqlClient;using System.Data;using GarageManager.DTO;
namespace GarageManager.DAL;
public sealed class GarageRepository
{
 public DataTable Customers(){using var c=Db.Open();using var d=new SqlDataAdapter("SELECT MaKH,TenKH,DienThoai,DiaChi FROM KhachHang ORDER BY TenKH",c);var t=new DataTable();d.Fill(t);return t;}
 public DataTable Vehicles(){using var c=Db.Open();using var d=new SqlDataAdapter("SELECT x.BienSo,x.MaKH,k.TenKH,x.HieuXe,x.NamSanXuat FROM Xe x JOIN KhachHang k ON k.MaKH=x.MaKH ORDER BY x.BienSo",c);var t=new DataTable();d.Fill(t);return t;}
 public DataTable SearchVehicles(string plate){using var c=Db.Open();using var d=new SqlDataAdapter("SELECT x.BienSo,x.MaKH,k.TenKH,x.HieuXe,x.NamSanXuat FROM Xe x JOIN KhachHang k ON k.MaKH=x.MaKH WHERE x.BienSo LIKE @plate ORDER BY x.BienSo",c);d.SelectCommand!.Parameters.Add("@plate",SqlDbType.VarChar,20).Value="%"+plate+"%";var t=new DataTable();d.Fill(t);return t;}
 public DataTable Parts(){using var c=Db.Open();using var d=new SqlDataAdapter("SELECT MaPhuTung,TenPhuTung,DonGia,SoLuongTon FROM PhuTung ORDER BY TenPhuTung",c);var t=new DataTable();d.Fill(t);return t;}
 public DataTable RepairOrders(){using var c=Db.Open();using var d=new SqlDataAdapter("SELECT p.MaPhieu,p.BienSo,x.HieuXe,p.NgayNhan,p.NoiDungSua,p.TongTien,p.TrangThai FROM PhieuSuaChua p JOIN Xe x ON x.BienSo=p.BienSo ORDER BY p.MaPhieu DESC",c);var t=new DataTable();d.Fill(t);return t;}
 public void SaveCustomer(int? id,string name,string phone,string address){using var c=Db.Open();using var x=new SqlCommand(id is null?"INSERT KhachHang(TenKH,DienThoai,DiaChi) VALUES(@n,@p,@a)":"UPDATE KhachHang SET TenKH=@n,DienThoai=@p,DiaChi=@a WHERE MaKH=@id",c);x.Parameters.Add("@n",SqlDbType.NVarChar,100).Value=name;x.Parameters.Add("@p",SqlDbType.VarChar,15).Value=phone;x.Parameters.Add("@a",SqlDbType.NVarChar,200).Value=address;if(id!=null)x.Parameters.Add("@id",SqlDbType.Int).Value=id;x.ExecuteNonQuery();}
 public void SaveVehicle(string plate,int customer,string make,int? year){using var c=Db.Open();using var x=new SqlCommand("IF EXISTS(SELECT 1 FROM Xe WHERE BienSo=@plate) UPDATE Xe SET MaKH=@kh,HieuXe=@make,NamSanXuat=@year WHERE BienSo=@plate ELSE INSERT Xe(BienSo,MaKH,HieuXe,NamSanXuat) VALUES(@plate,@kh,@make,@year)",c);x.Parameters.Add("@plate",SqlDbType.VarChar,20).Value=plate;x.Parameters.Add("@kh",SqlDbType.Int).Value=customer;x.Parameters.Add("@make",SqlDbType.NVarChar,50).Value=make;x.Parameters.Add("@year",SqlDbType.Int).Value=(object?)year??DBNull.Value;x.ExecuteNonQuery();}
 public void SavePart(int? id,string name,decimal price,int stock){using var c=Db.Open();using var x=new SqlCommand(id is null?"INSERT PhuTung(TenPhuTung,DonGia,SoLuongTon) VALUES(@n,@p,@s)":"UPDATE PhuTung SET TenPhuTung=@n,DonGia=@p,SoLuongTon=@s WHERE MaPhuTung=@id",c);x.Parameters.Add("@n",SqlDbType.NVarChar,150).Value=name;x.Parameters.Add("@p",SqlDbType.Decimal).Value=price;x.Parameters.Add("@s",SqlDbType.Int).Value=stock;if(id!=null)x.Parameters.Add("@id",SqlDbType.Int).Value=id;x.ExecuteNonQuery();}
 public void DeletePart(int id){using var c=Db.Open();using var x=new SqlCommand("DELETE PhuTung WHERE MaPhuTung=@id",c);x.Parameters.Add("@id",SqlDbType.Int).Value=id;x.ExecuteNonQuery();}
 public int CreateRepair(string plate,string description,IEnumerable<RepairLine> lines){var a=lines.ToList();if(a.Count==0)throw new InvalidOperationException("Thêm ít nhất một phụ tùng vào phiếu.");using var c=Db.Open();using var tr=c.BeginTransaction();try{decimal total=0;foreach(var line in a){decimal price;using(var get=new SqlCommand("SELECT DonGia FROM PhuTung WITH(UPDLOCK,HOLDLOCK) WHERE MaPhuTung=@id",c,tr)){get.Parameters.Add("@id",SqlDbType.Int).Value=line.PartId;var value=get.ExecuteScalar();if(value is null)throw new InvalidOperationException("Phụ tùng không tồn tại.");price=Convert.ToDecimal(value);}using(var stock=new SqlCommand("UPDATE PhuTung SET SoLuongTon=SoLuongTon-@q WHERE MaPhuTung=@id AND SoLuongTon>=@q",c,tr)){stock.Parameters.Add("@q",SqlDbType.Int).Value=line.Quantity;stock.Parameters.Add("@id",SqlDbType.Int).Value=line.PartId;if(stock.ExecuteNonQuery()!=1)throw new InvalidOperationException($"Kho không đủ phụ tùng: {line.PartName}. Phiếu đã rollback.");}total+=price*line.Quantity+line.Labor;}
 int ticket;using(var head=new SqlCommand("INSERT PhieuSuaChua(BienSo,NoiDungSua,TongTien,TrangThai) VALUES(@plate,@desc,@total,N'Đang sửa'); SELECT CAST(SCOPE_IDENTITY() AS int)",c,tr)){head.Parameters.Add("@plate",SqlDbType.VarChar,20).Value=plate;head.Parameters.Add("@desc",SqlDbType.NVarChar,-1).Value=description;head.Parameters.Add("@total",SqlDbType.Decimal).Value=total;ticket=(int)head.ExecuteScalar()!;}
 foreach(var line in a){using var x=new SqlCommand("INSERT ChiTietSuaChua(MaPhieu,MaPhuTung,SoLuong,TienCong,DonGia) SELECT @ticket,@part,@qty,@labor,DonGia FROM PhuTung WHERE MaPhuTung=@part",c,tr);x.Parameters.Add("@ticket",SqlDbType.Int).Value=ticket;x.Parameters.Add("@part",SqlDbType.Int).Value=line.PartId;x.Parameters.Add("@qty",SqlDbType.Int).Value=line.Quantity;x.Parameters.Add("@labor",SqlDbType.Decimal).Value=line.Labor;x.ExecuteNonQuery();}tr.Commit();return ticket;}catch{tr.Rollback();throw;}}
 public void MarkPaid(int id){using var c=Db.Open();using var x=new SqlCommand("UPDATE PhieuSuaChua SET TrangThai=N'Đã thanh toán' WHERE MaPhieu=@id AND TrangThai<>N'Đã thanh toán'",c);x.Parameters.Add("@id",SqlDbType.Int).Value=id;if(x.ExecuteNonQuery()==0)throw new InvalidOperationException("Phiếu không tồn tại hoặc đã thanh toán.");}
 public int Scalar(string sql){using var c=Db.Open();using var x=new SqlCommand(sql,c);return Convert.ToInt32(x.ExecuteScalar()??0);}
}
